<template><div class="page-shell narrow-page"><header class="page-header compact"><div><h1>歌手资料</h1><p class="page-subtitle">公开展示的艺名和简介。</p></div></header><StateMessage v-if="state==='loading'" state="loading" message="正在加载资料…"/><form v-else class="editor-form" @submit.prevent="save"><label>艺名<input v-model.trim="form.stageName" maxlength="100" required></label><label>简介<textarea v-model.trim="form.biography" maxlength="2000" rows="7"></textarea></label><p v-if="message" :class="success?'form-success':'form-error'" role="status">{{message}}</p><button class="primary-button" type="submit" :disabled="saving"><Save :size="18"/><span>{{saving?'保存中…':'保存资料'}}</span></button></form></div></template>
<script>
import {Save} from 'lucide-vue'; import StateMessage from '../components/StateMessage.vue'; import {artistStudio} from '../artist/client.js'; import {problemMessage} from '../ui/problem-message.js';
export default{name:'ArtistProfileView',components:{Save,StateMessage},data:()=>({state:'loading',saving:false,success:false,message:'',form:{stageName:'',biography:''}}),async mounted(){try{const profile=await artistStudio.profile(this.$store.state.auth.session.userId);this.form={stageName:profile.stageName,biography:profile.biography||''};this.state='ready';}catch(problem){this.state='ready';if(problem.status!==404)this.message=problemMessage(problem);}},methods:{async save(){this.saving=true;this.message='';try{const saved=await artistStudio.saveProfile({...this.form});this.form={stageName:saved.stageName,biography:saved.biography||''};this.success=true;this.message='歌手资料已保存。';}catch(problem){this.success=false;this.message=problemMessage(problem);}finally{this.saving=false;}}}};
</script>
